import sys

def read_int(): return int(sys.stdin.readline().strip())
def read_ints(): return map(int, sys.stdin.readline().strip().split())
def read_list(): return list(map(int, sys.stdin.readline().strip().split()))
def read_list2(): return list(map(int, sys.stdin.readline().strip()))
def read_str(): return sys.stdin.readline().strip()
def read_strs(): return sys.stdin.readline().strip().split()
def read_strs2(): return list(sys.stdin.readline().strip())

n, mod = read_ints()

edges_count = n * (n - 1) // 2
dp_array = [[[0] * (n + 1) for _ in range(edges_count + 1)] for _ in range(n + 1)]
dp_array[1][0][1] = 1

for i in range(1, n):
    for j in range(edges_count + 1):
        for k in range(n + 1):
            val = dp_array[i][j][k]
            if val == 0:
                continue
            dp_array[i + 1][j + i][i + 1] = (dp_array[i + 1][j + i][i + 1] + val) % mod
            for l in range(i):
                dp_array[i + 1][j + i - 1 - l][k] = (dp_array[i + 1][j + i - 1 - l][k] + val) % mod

partial_sum_dp = [[[0] * (edges_count + 1) for _ in range(n + 1)] for _ in range(n + 1)]
for i in range(n + 1):
    for k in range(n + 1):
        total = 0
        for j in range(edges_count + 1):
            total += dp_array[i][j][k]
            total %= mod
            partial_sum_dp[i][k][j] = total

cumulative_dp = [[[0] * (n + 1) for _ in range(edges_count + 1)] for _ in range(n + 1)]
for i in range(n + 1):
    for j in range(edges_count + 1):
        total = 0
        for k in range(n + 1):
            total += partial_sum_dp[i][k][j]
            total %= mod
            cumulative_dp[i][j][k] = total

answers = [0] * (n + 1)
for i in range(1, n + 1):
    answer = i * answers[i - 1] % mod
    for k in range(n + 1):
        for j in range(1, edges_count + 1):
            if dp_array[i][j][k] == 0:
                continue
            answer += dp_array[i][j][k] * (cumulative_dp[i][j - 1][-1] - cumulative_dp[i][j - 1][k])
            answer %= mod
    answers[i] = answer

print(answers[-1])
